void Diagnostics::add(ErrorCode c,Severity s,std::string m,std::size_t o){entries_.push_back({c,s,std::move(m),o});}
bool Diagnostics::ok()const{return std::none_of(entries_.begin(),entries_.end(),[](const Diagnostic&d){return d.code!=ErrorCode::ok&&d.severity!=Severity::info;});}
bool Diagnostics::has_errors()const{return !ok();} const std::vector<Diagnostic>& Diagnostics::entries()const{return entries_;}
std::string Diagnostics::summary()const{std::ostringstream o;for(auto&d:entries_)o<<severity_name(d.severity)<<":"<<int(d.code)<<"@"<<d.offset<<" "<<d.message<<"\n";return o.str();}
std::size_t Diagnostics::count(ErrorCode c)const{return std::count_if(entries_.begin(),entries_.end(),[&](auto&d){return d.code==c;});}
std::optional<ByteView> ByteView::slice(std::size_t o,std::size_t n)const{if(o>size||n>size-o)return{};return ByteView{data+o,n};}
std::string ByteView::ascii_preview(std::size_t m)const{std::string o;for(std::size_t i=0;i<std::min(size,m);++i)o.push_back(std::isprint(data[i])?char(data[i]):'.');return o;}
