std::uint16_t read_be16(const std::uint8_t*p){return std::uint16_t((p[0]<<8)|p[1]);} std::uint16_t read_le16(const std::uint8_t*p){return std::uint16_t((p[1]<<8)|p[0]);} std::uint32_t read_be32(const std::uint8_t*p){return(std::uint32_t(p[0])<<24)|(std::uint32_t(p[1])<<16)|(std::uint32_t(p[2])<<8)|p[3];} std::uint32_t read_le32(const std::uint8_t*p){return(std::uint32_t(p[3])<<24)|(std::uint32_t(p[2])<<16)|(std::uint32_t(p[1])<<8)|p[0];}
std::uint16_t internet_checksum(ByteView d,std::uint32_t s){std::size_t i=0;while(i+1<d.size){s+=read_be16(d.data+i);i+=2;}if(i<d.size)s+=std::uint16_t(d.data[i]<<8);while(s>>16)s=(s&0xffffu)+(s>>16);return std::uint16_t(~s);} std::uint32_t fnv1a(ByteView d){std::uint32_t h=2166136261u;for(std::size_t i=0;i<d.size;++i){h^=d.data[i];h*=16777619u;}return h;}
std::string trim(std::string_view s){std::size_t a=0,b=s.size();while(a<b&&std::isspace((unsigned char)s[a]))++a;while(b>a&&std::isspace((unsigned char)s[b-1]))--b;return std::string(s.substr(a,b-a));}
std::vector<std::string> split(std::string_view s,char d,bool keep){std::vector<std::string> o;std::size_t st=0;for(std::size_t i=0;i<=s.size();++i)if(i==s.size()||s[i]==d){if(keep||i>st)o.emplace_back(s.substr(st,i-st));st=i+1;}return o;}
std::string lower(std::string_view s){std::string o(s);std::transform(o.begin(),o.end(),o.begin(),[](unsigned char c){return std::tolower(c);});return o;} std::string upper(std::string_view s){std::string o(s);std::transform(o.begin(),o.end(),o.begin(),[](unsigned char c){return std::toupper(c);});return o;} bool starts_with(std::string_view s,std::string_view p){return s.size()>=p.size()&&s.substr(0,p.size())==p;} bool ends_with(std::string_view s,std::string_view p){return s.size()>=p.size()&&s.substr(s.size()-p.size())==p;}
std::string strip_quotes(std::string_view s){auto t=trim(s);if(t.size()>=2&&((t.front()=='"'&&t.back()=='"')||(t.front()=='\''&&t.back()=='\'')))return t.substr(1,t.size()-2);return t;} bool is_hex(std::string_view s){return!s.empty()&&std::all_of(s.begin(),s.end(),[](unsigned char c){return std::isxdigit(c);});} bool is_decimal(std::string_view s){return!s.empty()&&std::all_of(s.begin(),s.end(),[](unsigned char c){return std::isdigit(c);});}
std::optional<std::uint64_t> parse_u64(std::string_view s,int b){auto t=trim(s);if(t.empty())return{};char*e=nullptr;errno=0;auto v=std::strtoull(t.c_str(),&e,b);if(errno||e!=t.c_str()+t.size())return{};return v;} std::string hex_encode(ByteView d){std::ostringstream o;o<<std::hex<<std::setfill('0');for(std::size_t i=0;i<d.size;++i)o<<std::setw(2)<<unsigned(d.data[i]);return o.str();} std::string sanitize_token(std::string_view s){std::string o;for(unsigned char c:s)if(std::isalnum(c)||c=='.'||c=='-'||c=='_'||c==':'||c=='/'||c=='@')o.push_back(char(c));return o;}
std::string IPv4Address::str()const{std::ostringstream o;o<<((value>>24)&255)<<'.'<<((value>>16)&255)<<'.'<<((value>>8)&255)<<'.'<<(value&255);return o.str();} bool IPv4Address::is_private()const{return(value&0xff000000u)==0x0a000000u||(value&0xfff00000u)==0xac100000u||(value&0xffff0000u)==0xc0a80000u;} bool IPv4Address::is_loopback()const{return(value&0xff000000u)==0x7f000000u;} bool IPv4Address::is_multicast()const{return(value&0xf0000000u)==0xe0000000u;} bool IPv4Address::is_unspecified()const{return value==0;}
std::uint32_t mask_for_prefix(std::uint8_t p){if(p==0)return 0;if(p>=32)return 0xffffffffu;return 0xffffffffu<<(32-p);} bool CidrRange::contains(IPv4Address ip)const{auto m=mask_for_prefix(prefix);return valid&&ip.valid&&((ip.value&m)==(network.value&m));} std::string CidrRange::str()const{return network.str()+"/"+std::to_string(prefix);} std::optional<IPv4Address> parse_ipv4(std::string_view s){auto parts=split(trim(s),'.',true);if(parts.size()!=4)return{};std::uint32_t v=0;for(auto&p:parts){if(!is_decimal(p))return{};auto n=parse_u64(p);if(!n||*n>255)return{};v=(v<<8)|std::uint32_t(*n);}return IPv4Address{v,true};}
std::optional<CidrRange> parse_cidr(std::string_view s){auto t=trim(s);auto x=t.find('/');if(x==std::string::npos)return{};auto ip=parse_ipv4(t.substr(0,x));auto p=parse_u64(t.substr(x+1));if(!ip||!p||*p>32)return{};auto pr=std::uint8_t(*p);return CidrRange{IPv4Address{ip->value&mask_for_prefix(pr),true},pr,true};} IPv4Address ipv4_from_be(std::uint32_t v){return IPv4Address{v,true};}
bool domain_like(std::string_view s){auto t=trim(s);if(t.size()<3||t.size()>253||t.find('.')==std::string::npos)return false;bool alpha=false,lastdot=true;for(unsigned char c:t){if(std::isalpha(c))alpha=true;if(c=='.'){if(lastdot)return false;lastdot=true;}else if(std::isalnum(c)||c=='-')lastdot=false;else return false;}return alpha&&!lastdot;} bool hash_like(std::string_view s){auto t=trim(s);return(t.size()==32||t.size()==40||t.size()==64||t.size()==128)&&is_hex(t);} bool url_like(std::string_view s){auto l=lower(trim(s));return starts_with(l,"http://")||starts_with(l,"https://");}
std::string normalize_domain(std::string_view s){auto t=lower(strip_quotes(s));while(!t.empty()&&t.back()=='.')t.pop_back();return t;} std::string normalize_url(std::string_view s){auto t=strip_quotes(s);auto l=lower(t);auto p=l.find("://");if(p==std::string::npos)return l;auto rest=t.substr(p+3);auto slash=rest.find('/');auto host=normalize_domain(slash==std::string::npos?rest:rest.substr(0,slash));return l.substr(0,p+3)+host+(slash==std::string::npos?"/":rest.substr(slash));}
std::optional<std::chrono::system_clock::time_point> parse_timestamp(std::string_view s){if(auto e=parse_u64(s))return std::chrono::system_clock::time_point{std::chrono::seconds(*e)};return{};} std::string severity_name(Severity s){switch(s){case Severity::info:return"info";case Severity::low:return"low";case Severity::medium:return"medium";case Severity::high:return"high";case Severity::critical:return"critical";}return"unknown";} Severity parse_severity(std::string_view s,Severity f){auto l=lower(trim(s));if(l=="info")return Severity::info;if(l=="low")return Severity::low;if(l=="medium"||l=="med")return Severity::medium;if(l=="high")return Severity::high;if(l=="critical"||l=="crit")return Severity::critical;return f;}
